    15→#include "Materials/MaterialInstanceDynamic.h"
    16→#include "Cosmetic/WjWorldCosmeticSubsystem.h"
    17→#include "WjWorldLogCategories.h"
    18→
    19→#if WITH_STEAM
    20→#include "steam/steam_api.h"
    21→#endif
    22→
    23→const FString AWjWorldTreasureChestActor::ConfigSection = TEXT("TreasureChestCooldown");
    24→
    25→AWjWorldTreasureChestActor::AWjWorldTreasureChestActor()
    26→{
    27→	PrimaryActorTick.bCanEverTick = true;
    28→	PrimaryActorTick.bStartWithTickEnabled = false;
    29→
    30→	// 뚜껑 메시
    31→	LidMeshComponent = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("LidMeshComponent"));
    32→	LidMeshComponent->SetupAttachment(MeshComponent);
    33→	LidMeshComponent->SetRelativeLocation(FVector(0.0f, -60.0f, -60.0f));
    34→	LidMeshComponent->SetCollisionEnabled(ECollisionEnabled::NoCollision);
    35→
    36→	// 상호작용 트리거
    37→	InteractionTrigger = CreateDefaultSubobject<UBoxComponent>(TEXT("InteractionTrigger"));
    38→	InteractionTrigger->SetupAttachment(MeshComponent);
    39→	InteractionTrigger->SetBoxExtent(FVector(150.0f, 150.0f, 100.0f));
    40→	InteractionTrigger->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
    41→	InteractionTrigger->SetCollisionResponseToAllChannels(ECR_Ignore);
    42→	InteractionTrigger->SetCollisionResponseToChannel(ECC_Pawn, ECR_Overlap);
    43→
    44→	// 위젯 컴포넌트
    45→	InteractionWidgetComponent = CreateDefaultSubobject<UWidgetComponent>(TEXT("InteractionWidget"));
    46→	InteractionWidgetComponent->SetupAttachment(MeshComponent);
    47→	InteractionWidgetComponent->SetRelativeLocation(FVector(0.0f, 0.0f, 100.0f));
    48→	InteractionWidgetComponent->SetWidgetSpace(EWidgetSpace::Screen);
    49→	InteractionWidgetComponent->SetDrawSize(FVector2D(300.0f, 60.0f));
    50→	InteractionWidgetComponent->SetVisibility(false);
    51→}
    52→
    53→void AWjWorldTreasureChestActor::BeginPlay()
    54→{
    55→	Super::BeginPlay();
    56→
    57→	// 오버랩 이벤트 바인딩
    58→	if (InteractionTrigger)
    59→	{
    60→		InteractionTrigger->OnComponentBeginOverlap.AddDynamic(this, &AWjWorldTreasureChestActor::OnTriggerBeginOverlap);
    61→		InteractionTrigger->OnComponentEndOverlap.AddDynamic(this, &AWjWorldTreasureChestActor::OnTriggerEndOverlap);
    62→	}
    63→
    64→	// UI 위젯 설정
    65→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    66→	if (Settings && !Settings->TreasureChestWidgetClass.IsNull())
    67→	{
    68→		UClass* WidgetClass = Settings->TreasureChestWidgetClass.LoadSynchronous();
    69→		if (WidgetClass && InteractionWidgetComponent)
    70→		{
    71→			InteractionWidget = Cast<UInteractionWidget>(CreateWidget<UUserWidget>(GetWorld(), WidgetClass));
    72→			if (InteractionWidget)
    73→			{
    74→				InteractionWidgetComponent->SetWidget(InteractionWidget);
    75→			}
    76→		}
    77→	}
    78→
    79→	// 쿨타임 비주얼 초기화
    80→	if (IsOnCooldown())
    81→	{
    82→		ApplyCooldownVisual();
    83→		SetLidOpenImmediate();
    84→	}
    85→	else
    86→	{
    87→		SetLidCloseImmediate();
    88→	}
    89→}
    90→
    91→void AWjWorldTreasureChestActor::EndPlay(const EEndPlayReason::Type EndPlayReason)
    92→{
    93→	// 입력 해제 + 바인딩 정리
    94→	if (InteractingPlayer)
    95→	{
    96→		APlayerController* PC = Cast<APlayerController>(InteractingPlayer->GetController());
    97→		if (PC)
    98→		{
    99→			DisableInput(PC);
   100→		}
   101→	}
   102→	if (InputComponent)
   103→	{
   104→		InputComponent->ClearActionBindings();
   105→	}
   106→	bInputBound = false;
   107→
   108→	// 쿨타임 UI 타이머 정리
   109→	GetWorldTimerManager().ClearTimer(CooldownUITimerHandle);
   110→
   111→	Super::EndPlay(EndPlayReason);
   112→}
   113→
   114→void AWjWorldTreasureChestActor::Tick(float DeltaTime)
   115→{
   116→	Super::Tick(DeltaTime);
   117→
   118→	if (!bLidAnimating || !LidMeshComponent)
   119→	{
   120→		SetActorTickEnabled(false);
   121→		bLidAnimating = false;
   122→		return;
   123→	}
   124→
   125→	float TargetRoll = bLidOpening ? LidOpenedRoll : LidClosedRoll;
   126→	float Direction = (TargetRoll > LidCurrentRoll) ? 1.0f : -1.0f;
   127→	LidCurrentRoll += Direction * LidAnimSpeed * DeltaTime;
   128→
   129→	// 목표 도달 확인
   130→	bool bReached = (Direction > 0.0f)
   131→		? (LidCurrentRoll >= TargetRoll)
   132→		: (LidCurrentRoll <= TargetRoll);
   133→
   134→	if (bReached)
   135→	{
   136→		LidCurrentRoll = TargetRoll;
   137→		bLidAnimating = false;
   138→		SetActorTickEnabled(false);
   139→	}
   140→
   141→	FRotator LidRot = LidMeshComponent->GetRelativeRotation();
   142→	LidRot.Roll = LidCurrentRoll;
   143→	LidMeshComponent->SetRelativeRotation(LidRot);
   144→}
   145→
   146→void AWjWorldTreasureChestActor::OnTriggerBeginOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
   147→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
   148→{
   149→	APawn* Pawn = Cast<APawn>(OtherActor);
   150→	if (!Pawn || !Pawn->IsPlayerControlled())
   151→	{
   152→		return;
   153→	}
   154→
   155→	bPlayerInRange = true;
   156→	InteractingPlayer = Pawn;
   157→
   158→	// 입력 바인딩 (중복 방지)
   159→	APlayerController* PC = Cast<APlayerController>(Pawn->GetController());
   160→	if (PC)
   161→	{
   162→		EnableInput(PC);
   163→
   164→		if (!bInputBound)
   165→		{
   166→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   167→			if (Settings && InputComponent)
   168→			{
   169→				UInputAction* IA = Settings->TreasureChestInteractAction.LoadSynchronous();
   170→				if (IA)
   171→				{
   172→					if (UEnhancedInputComponent* EIC = Cast<UEnhancedInputComponent>(InputComponent))
   173→					{
   174→						EIC->BindAction(IA, ETriggerEvent::Started, this, &AWjWorldTreasureChestActor::OnInteract);
   175→						bInputBound = true;
   176→					}
   177→				}
   178→			}
   179→		}
   180→	}
   181→
   182→	// 쿨타임 만료 시 비주얼 복원 (Fix 3)
   183→	if (!IsOnCooldown())
   184→	{
   185→		RemoveCooldownVisual();
   186→		PlayLidClose();
   187→	}
   188→
   189→	ShowInteractionUI();
   190→
   191→	// 쿨타임 중이면 UI 실시간 갱신 타이머 시작 (Fix 4)
   192→	if (IsOnCooldown())
   193→	{
   194→		GetWorldTimerManager().SetTimer(CooldownUITimerHandle, this,
   195→			&AWjWorldTreasureChestActor::UpdateInteractionUI, 1.0f, true);
   196→	}
   197→
   198→	UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Player entered range"));
   199→}
