   201→void AWjWorldTreasureChestActor::OnTriggerEndOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
   202→	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex)
   203→{
   204→	APawn* Pawn = Cast<APawn>(OtherActor);
   205→	if (!Pawn || !Pawn->IsPlayerControlled())
   206→	{
   207→		return;
   208→	}
   209→
   210→	// 입력 해제 + 바인딩 정리
   211→	APlayerController* PC = Cast<APlayerController>(Pawn->GetController());
   212→	if (PC)
   213→	{
   214→		DisableInput(PC);
   215→	}
   216→	if (InputComponent)
   217→	{
   218→		InputComponent->ClearActionBindings();
   219→	}
   220→	bInputBound = false;
   221→
   222→	// 쿨타임 UI 타이머 정리
   223→	GetWorldTimerManager().ClearTimer(CooldownUITimerHandle);
   224→
   225→	bPlayerInRange = false;
   226→	InteractingPlayer = nullptr;
   227→
   228→	HideInteractionUI();
   229→
   230→	UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Player left range"));
   231→}
   232→
   233→void AWjWorldTreasureChestActor::OnInteract()
   234→{
   235→	if (!bPlayerInRange || !InteractingPlayer)
   236→	{
   237→		return;
   238→	}
   239→
   240→	// 로컬 쿨타임 확인 (UI용, Steam에서는 서버도 이중 검증)
   241→	if (IsOnCooldown())
   242→	{
   243→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: On cooldown, remaining: %s"),
   244→			*GetRemainingCooldown().ToString());
   245→		return;
   246→	}
   247→
   248→	// 보상 지급 시도
   249→	if (!TryGrantReward())
   250→	{
   251→		UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Reward grant failed (Steam cooldown or error)"));
   252→		return;
   253→	}
   254→
   255→	// 쿨타임 타임스탬프 저장 (UI 표시용)
   256→	SaveCooldown();
   257→
   258→	// 뚜껑 열기 연출
   259→	PlayLidOpen();
   260→
   261→	// 비주얼 전환
   262→	ApplyCooldownVisual();
   263→
   264→	// UI 갱신
   265→	UpdateInteractionUI();
   266→}
   267→
   268→bool AWjWorldTreasureChestActor::TryGrantReward()
   269→{
   270→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   271→	if (!Settings)
   272→	{
   273→		return false;
   274→	}
   275→
   276→#if WITH_STEAM
   277→	ISteamInventory* SteamInv = SteamInventory();
   278→	if (SteamInv)
   279→	{
   280→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   281→		int32 GeneratorDefId = Settings->TreasureChestGeneratorStartDefId + ChestIndex;
   282→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   283→
   284→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   285→		{
   286→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 요청 성공 (DefId: %d)"),
   287→				ChestIndex, GeneratorDefId);
   288→			SteamInv->DestroyResult(ResultHandle);
   289→
   290→			// 인벤토리 갱신으로 잔액 반영
   291→			UGameInstance* GI = GetGameInstance();
   292→			if (GI)
   293→			{
   294→				UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   295→				if (CosmeticSub)
   296→				{
   297→					CosmeticSub->RequestInventoryRefresh();
   298→				}
   299→			}
   300→
   301→			return true;
   302→		}
   303→		else
   304→		{
   305→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 호출 실패 (DefId: %d)"),
   306→				ChestIndex, GeneratorDefId);
   307→			return false;
   308→		}
   309→	}
   310→#endif
   311→
   312→	// 비Steam 폴백: 로컬 재화 부여
   313→	int32 RewardAmount = Settings->TreasureChestCoinReward;
   314→	UGameInstance* GI = GetGameInstance();
   315→	if (GI)
   316→	{
   317→		UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   318→		if (CurrencySub)
   319→		{
   320→			CurrencySub->GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   321→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest: 로컬 보상 %d Coin 지급"), RewardAmount);
   322→		}
   323→	}
   324→
   325→	return true;
   326→}
