   345→void AWjWorldTreasureChestActor::UpdateInteractionUI()
   346→{
   347→	if (!InteractionWidget)
   348→	{
   349→		return;
   350→	}
   351→
   352→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   353→	int32 RewardAmount = Settings ? Settings->TreasureChestCoinReward : 50;
   354→
   355→	if (IsOnCooldown())
   356→	{
   357→		FTimespan Remaining = GetRemainingCooldown();
   358→		int32 Hours = static_cast<int32>(Remaining.GetTotalHours());
   359→		int32 Minutes = Remaining.GetMinutes();
   360→		int32 Seconds = Remaining.GetSeconds();
   361→
   362→		FString CooldownText = FString::Printf(TEXT("Next open: %02d:%02d:%02d"), Hours, Minutes, Seconds);
   363→		InteractionWidget->SetInteractionText(CooldownText);
   364→	}
   365→	else
   366→	{
   367→		// 쿨타임 만료 감지 → 타이머 정지 + 비주얼 복원
   368→		GetWorldTimerManager().ClearTimer(CooldownUITimerHandle);
   369→		RemoveCooldownVisual();
   370→		PlayLidClose();
   371→
   372→		FString InteractText = FString::Printf(TEXT("Open Chest (%d Coin)"), RewardAmount);
   373→		InteractionWidget->SetInteractionText(InteractText);
   374→	}
   375→}
