   392→
   393→bool AWjWorldTreasureChestActor::IsOnCooldown() const
   394→{
   395→	FString Key = GetChestKey();
   396→	FString LastOpenedStr;
   397→	FString ConfigPath = GetConfigPath();
   398→
   399→	if (GConfig->GetString(*ConfigSection, *Key, LastOpenedStr, ConfigPath))
   400→	{
   401→		FDateTime LastOpened;
   402→		if (FDateTime::ParseIso8601(*LastOpenedStr, LastOpened))
   403→		{
   404→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   405→			float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   406→			return (FDateTime::UtcNow() - LastOpened).GetTotalSeconds() < CooldownSeconds;
   407→		}
   408→	}
   409→	return false;
   410→}
   411→
   412→FTimespan AWjWorldTreasureChestActor::GetRemainingCooldown() const
   413→{
   414→	FString Key = GetChestKey();
   415→	FString LastOpenedStr;
   416→	FString ConfigPath = GetConfigPath();
   417→
   418→	if (GConfig->GetString(*ConfigSection, *Key, LastOpenedStr, ConfigPath))
   419→	{
   420→		FDateTime LastOpened;
   421→		if (FDateTime::ParseIso8601(*LastOpenedStr, LastOpened))
   422→		{
   423→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   424→			float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   425→
   426→			FDateTime CooldownEnd = LastOpened + FTimespan::FromSeconds(CooldownSeconds);
   427→			FTimespan Remaining = CooldownEnd - FDateTime::UtcNow();
   428→
   429→			if (Remaining.GetTotalSeconds() > 0)
   430→			{
   431→				return Remaining;
   432→			}
   433→		}
   434→	}
   435→	return FTimespan::Zero();
   436→}
   437→
   438→void AWjWorldTreasureChestActor::SaveCooldown()
   439→{
   440→	FString Key = GetChestKey();
   441→	FString ConfigPath = GetConfigPath();
   442→
   443→	GConfig->SetString(*ConfigSection, *Key, *FDateTime::UtcNow().ToIso8601(), ConfigPath);
   444→	GConfig->Flush(false, ConfigPath);
   445→
   446→	UE_LOG(LogWjWorld, Log, TEXT("TreasureChest: Cooldown saved for %s"), *Key);
   447→}
