   465→void AWjWorldTreasureChestActor::SetLidOpenImmediate()
   466→{
   467→	LidCurrentRoll = LidOpenedRoll;
   468→	bLidAnimating = false;
   469→
   470→	if (LidMeshComponent)
   471→	{
   472→		FRotator LidRot = LidMeshComponent->GetRelativeRotation();
