   490→
   491→// === Visual ===
   492→
   493→void AWjWorldTreasureChestActor::ApplyCooldownVisual()
   494→{
   495→	if (!MeshComponent)
   496→	{
   497→		return;
   498→	}
   499→
   500→	int32 NumMats = MeshComponent->GetNumMaterials();
   501→	for (int32 i = 0; i < NumMats; ++i)
   502→	{
   503→		UMaterialInstanceDynamic* DMI = MeshComponent->CreateAndSetMaterialInstanceDynamic(i);
   504→		if (DMI)
   505→		{
   506→			// 어두운 회색 틴트
   507→			DMI->SetVectorParameterValue(TEXT("BaseColor"), FLinearColor(0.3f, 0.3f, 0.3f, 1.0f));
   508→			DMI->SetScalarParameterValue(TEXT("Opacity"), 0.5f);
   509→		}
   510→	}
   511→}
   512→
   513→void AWjWorldTreasureChestActor::RemoveCooldownVisual()
   514→{
   515→	// PlacedObjectActor의 원본 머티리얼 복원 패턴과 동일
   516→	// 메시 재로드로 원본 머티리얼 복원
   517→	if (MeshComponent && MeshComponent->GetStaticMesh())
   518→	{
   519→		UStaticMesh* CurrentMesh = MeshComponent->GetStaticMesh();
   520→		int32 NumMats = CurrentMesh->GetStaticMaterials().Num();
   521→		for (int32 i = 0; i < NumMats; ++i)
   522→		{
   523→			MeshComponent->SetMaterial(i, CurrentMesh->GetMaterial(i));
   524→		}
   525→	}
   526→}
