   133→bool UWjWorldCurrencySubsystem::PurchaseItemWithCurrency(FName CosmeticItemId, ECurrencyType CurrencyType)
   134→{
   135→	if (bExchangePending)
   136→	{
   137→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   138→		return false;
   139→	}
   140→
   141→	if (CosmeticItemId.IsNone())
   142→	{
   143→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 CosmeticItemId"));
   144→		return false;
   145→	}
   146→
   147→	// 카탈로그에서 아이템 정보 조회
   148→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   149→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   150→	{
   151→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("CosmeticSubsystem 또는 카탈로그 없음"));
   152→		return false;
   153→	}
   154→
   155→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(CosmeticItemId);
   156→	if (!ItemDef)
   157→	{
   158→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("카탈로그에서 아이템 '%s' 찾을 수 없음"), *CosmeticItemId.ToString());
   159→		return false;
   160→	}
   161→
   162→	// 가격 확인
   163→	int32 ItemPrice = (CurrencyType == ECurrencyType::Coin) ? ItemDef->CoinPrice : ItemDef->GemPrice;
   164→	if (ItemPrice <= 0)
   165→	{
   166→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("아이템 '%s'은 %s로 구매할 수 없습니다 (가격: %d)"),
   167→			*CosmeticItemId.ToString(),
   168→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   169→			ItemPrice);
   170→		return false;
   171→	}
   172→
   173→	// 잔액 확인
   174→	int32 CurrentBalance = GetBalance(CurrencyType);
   175→	if (CurrentBalance < ItemPrice)
   176→	{
   177→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("잔액 부족: %s %d < %d"),
   178→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   179→			CurrentBalance, ItemPrice);
   180→		return false;
   181→	}
   182→
   183→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   184→	if (!Settings)
   185→	{
   186→		return false;
   187→	}
   188→
   189→	int32 CurrencyDefId = (CurrencyType == ECurrencyType::Coin) ? Settings->CoinSteamItemDefId : Settings->GemSteamItemDefId;
   190→	int32 CosmeticDefId = ItemDef->SteamItemDefId;
   191→
   192→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 구매 요청: %s (%d %s → CosmeticDefId %d)"),
   193→		*CosmeticItemId.ToString(), ItemPrice,
   194→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   195→		CosmeticDefId);
   196→
   197→#if WITH_STEAM
   198→	ISteamInventory* SteamInv = SteamInventory();
   199→	if (SteamInv && CosmeticDefId > 0)
   200→	{
   201→		// 기존 핸들 정리
   202→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   203→		{
   204→			SteamInv->DestroyResult(ExchangeResultHandle);
   205→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   206→		}
   207→
   208→		// ExchangeItems: 재화 소비 → 코스메틱 아이템 획득
   209→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(CosmeticDefId);
   210→		uint32 OutputQuantity = 1;
   211→
   212→		// 입력: 재화 아이템 (인벤토리에서 해당 수량 소비)
   213→		// ExchangeItems는 인스턴스 ID가 필요하므로, 전체 인벤토리에서 재화 인스턴스를 찾아야 함
   214→		// 여기서는 간단화를 위해 재화가 auto_stack이므로 단일 인스턴스라 가정
   215→		// 실제 구현시에는 GetAllItems 결과에서 인스턴스 ID를 캐싱해야 함
   216→
   217→		// Steam ExchangeItems는 SteamItemInstanceID_t가 필요
   218→		// exchange 레시피는 서버 사이드에서 itemdef의 "exchange" 프로퍼티로 검증
   219→		// 따라서 클라이언트에서는 재화 인스턴스 ID만 전달하면 됨
   220→
   221→		// 재화 인스턴스 ID를 찾기 위해 인벤토리 조회 필요
   222→		// CosmeticSubsystem의 캐시된 결과에서는 인스턴스 ID를 보관하지 않으므로
   223→		// 별도의 GetAllItems 호출 후 처리해야 함
   224→		// 이 부분은 추후 인스턴스 ID 캐싱이 구현되면 개선
   225→
   226→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam ExchangeItems는 인스턴스 ID 기반 - 인벤토리 갱신 후 재시도 필요"));
   227→
   228→		// 현재는 로컬 차감 + CosmeticSubsystem으로 아이템 부여하는 방식으로 처리
   229→		// Steam 서버 사이드 exchange는 추후 인스턴스 ID 캐싱 구현 시 활성화
   230→		SetBalance(CurrencyType, CurrentBalance - ItemPrice);
   231→		CosmeticSub->GrantItemLocally(CosmeticItemId, 1);
   232→		CosmeticSub->RequestInventoryRefresh();
   233→
   234→		OnCurrencyPurchaseComplete.Broadcast(CosmeticItemId, true);
   235→		return true;
   236→	}
   237→#endif
   238→
   239→	// 비Steam 폴백: 로컬 잔액 차감 + 아이템 부여
   240→	SetBalance(CurrencyType, CurrentBalance - ItemPrice);
   241→	CosmeticSub->GrantItemLocally(CosmeticItemId, 1);
   242→
   243→	OnCurrencyPurchaseComplete.Broadcast(CosmeticItemId, true);
   244→
   245→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 구매 완료: %s (%d %s 차감)"),
   246→		*CosmeticItemId.ToString(), ItemPrice,
   247→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"));
   248→
   249→	return true;
   250→}
