   423→void UWjWorldCurrencySubsystem::PollExchangeResult()
   424→{
   425→#if WITH_STEAM
   426→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   427→	{
   428→		StopExchangePolling();
   429→		return;
   430→	}
   431→
   432→	ISteamInventory* SteamInv = SteamInventory();
   433→	if (!SteamInv)
   434→	{
   435→		StopExchangePolling();
   436→		bExchangePending = false;
   437→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   438→		PendingExchangeItemId = NAME_None;
   439→		return;
   440→	}
   441→
   442→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   443→	if (Status == k_EResultPending)
   444→	{
   445→		return;
   446→	}
   447→
   448→	bool bSuccess = (Status == k_EResultOK);
   449→	if (bSuccess)
   450→	{
   451→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   452→
   453→		// 인벤토리 갱신
   454→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   455→		if (CosmeticSub)
   456→		{
   457→			CosmeticSub->RequestInventoryRefresh();
   458→		}
   459→	}
   460→	else
   461→	{
   462→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   463→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   464→	}
   465→
   466→	SteamInv->DestroyResult(ExchangeResultHandle);
   467→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   468→
   469→	bExchangePending = false;
   470→	OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   471→	PendingExchangeItemId = NAME_None;
   472→
   473→	StopExchangePolling();
   474→#else
   475→	StopExchangePolling();
   476→#endif
   477→}
