   241→void UCosmeticMainWindow::OnActionButtonClicked()
   242→{
   243→	if (SelectedItemId.IsNone())
   244→	{
   245→		return;
   246→	}
   247→
   248→	UGameInstance* GI = GetGameInstance();
   249→	if (!GI)
   250→	{
   251→		return;
   252→	}
   253→
   254→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   255→	if (!CosmeticSub)
   256→	{
   257→		return;
   258→	}
   259→
   260→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   261→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   262→
   263→	if (CurrentMode == ECosmeticWindowMode::Shop)
   264→	{
   265→		// 상점 모드
   266→		if (CosmeticSub->HasItem(SelectedItemId))
   267→		{
   268→			// 보유 중인 아이템 → 장착 또는 해제
   269→			if (EquippedItem == SelectedItemId)
   270→			{
   271→				CosmeticSub->UnequipSlot(CurrentSlot);
   272→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d (from Shop)"), static_cast<int32>(CurrentSlot));
   273→			}
   274→			else
   275→			{
   276→				CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   277→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d (from Shop)"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   278→			}
   279→			CosmeticSub->SaveLoadoutToLocal();
   280→		}
   281→		else
   282→		{
   283→			// 미보유 아이템 → 재화 구매 우선, 재화 가격 없는 경우만 Steam 실결제
   284→			const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog() ? CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId) : nullptr;
   285→			UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   286→
   287→			bool bHasCurrencyPrice = ItemDef && (ItemDef->CoinPrice > 0 || ItemDef->GemPrice > 0);
   288→			bool bCurrencyPurchased = false;
   289→
   290→			if (ItemDef && CurrencySub)
   291→			{
   292→				// Coin 잔액 충분 시 Coin으로 구매
   293→				if (ItemDef->CoinPrice > 0 && CurrencySub->GetBalance(ECurrencyType::Coin) >= ItemDef->CoinPrice)
   294→				{
   295→					bCurrencyPurchased = CurrencySub->PurchaseItemWithCurrency(SelectedItemId, ECurrencyType::Coin);
   296→					if (bCurrencyPurchased)
   297→					{
   298→						UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Coin purchase requested for %s"), *SelectedItemId.ToString());
   299→					}
   300→				}
   301→
   302→				// Coin 구매 실패 시 Gem 잔액 충분하면 Gem으로 구매
   303→				if (!bCurrencyPurchased && ItemDef->GemPrice > 0 && CurrencySub->GetBalance(ECurrencyType::Gem) >= ItemDef->GemPrice)
   304→				{
   305→					bCurrencyPurchased = CurrencySub->PurchaseItemWithCurrency(SelectedItemId, ECurrencyType::Gem);
   306→					if (bCurrencyPurchased)
   307→					{
   308→						UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Gem purchase requested for %s"), *SelectedItemId.ToString());
   309→					}
   310→				}
   311→			}
   312→
   313→			if (bCurrencyPurchased)
   314→			{
   315→				// 재화 구매 성공 → 알림은 OnCurrencyPurchaseComplete에서 처리
   316→			}
   317→			else if (bHasCurrencyPrice)
   318→			{
   319→				// 재화 가격이 있지만 잔액 부족 → Steam 실결제로 넘어가지 않음
   320→				ShowNotification(NSLOCTEXT("Cosmetic", "InsufficientBalanceNotify", "잔액이 부족합니다"), false);
   321→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Insufficient balance for %s"), *SelectedItemId.ToString());
   322→			}
   323→			else
   324→			{
   325→				// 재화 가격 없음 → Steam 실결제
   326→				UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   327→				if (PurchaseSub && !PurchaseSub->IsPurchasePending())
   328→				{
   329→					PurchaseSub->RequestPurchase(SelectedItemId);
   330→					UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Steam purchase requested for %s"), *SelectedItemId.ToString());
   331→				}
   332→			}
   333→		}
   334→	}
   335→	else
   336→	{
   337→		// 인벤토리 모드: 장착 또는 해제
   338→		if (EquippedItem == SelectedItemId)
   339→		{
   340→			CosmeticSub->UnequipSlot(CurrentSlot);
   341→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d"), static_cast<int32>(CurrentSlot));
   342→		}
   343→		else
   344→		{
   345→			CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   346→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   347→		}
   348→		CosmeticSub->SaveLoadoutToLocal();
   349→	}
   350→}
