   541→void UCosmeticMainWindow::RefreshActionButton()
   542→{
   543→	if (!ActionButton || !ActionButtonText)
   544→	{
   545→		return;
   546→	}
   547→
   548→	if (SelectedItemId.IsNone())
   549→	{
   550→		ActionButton->SetIsEnabled(false);
   551→		ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "SelectItem", "아이템 선택"));
   552→		return;
   553→	}
   554→
   555→	UGameInstance* GI = GetGameInstance();
   556→	if (!GI)
   557→	{
   558→		return;
   559→	}
   560→
   561→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   562→	if (!CosmeticSub)
   563→	{
   564→		return;
   565→	}
   566→
   567→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   568→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   569→	bool bIsEquipped = (EquippedItem == SelectedItemId);
   570→
   571→	// 장착/해제 분기에서 기본 색상 리셋
   572→	auto ResetButtonTextColor = [this]()
   573→	{
   574→		ActionButtonText->SetColorAndOpacity(FSlateColor(FLinearColor::White));
   575→	};
   576→
   577→	if (CurrentMode == ECosmeticWindowMode::Shop)
   578→	{
   579→		// 상점 모드
   580→		if (CosmeticSub->HasItem(SelectedItemId))
   581→		{
   582→			// 보유 중인 아이템 → 장착/해제 가능
   583→			ActionButton->SetIsEnabled(true);
   584→			ResetButtonTextColor();
   585→
   586→			if (bIsEquipped)
   587→			{
   588→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   589→			}
   590→			else
   591→			{
   592→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   593→			}
   594→		}
   595→		else
   596→		{
   597→			// 미보유 아이템 → 구매
   598→			UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   599→			bool bPending = PurchaseSub && PurchaseSub->IsPurchasePending();
   600→
   601→			const FCosmeticItemDefinition* ItemDef = nullptr;
   602→			if (CosmeticSub->GetCatalog())
   603→			{
   604→				ItemDef = CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId);
   605→			}
   606→
   607→			UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   608→
   609→			bool bHasCoinPrice = ItemDef && ItemDef->CoinPrice > 0;
   610→			bool bHasGemPrice = ItemDef && ItemDef->GemPrice > 0;
   611→			bool bCoinAffordable = bHasCoinPrice && CurrencySub && CurrencySub->GetBalance(ECurrencyType::Coin) >= ItemDef->CoinPrice;
   612→			bool bGemAffordable = bHasGemPrice && CurrencySub && CurrencySub->GetBalance(ECurrencyType::Gem) >= ItemDef->GemPrice;
   613→
   614→			if (bPending)
   615→			{
   616→				ActionButton->SetIsEnabled(false);
   617→				ResetButtonTextColor();
   618→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Purchasing", "구매 중..."));
   619→			}
   620→			else if (bCoinAffordable)
   621→			{
   622→				ActionButton->SetIsEnabled(true);
   623→				ResetButtonTextColor();
   624→				ActionButtonText->SetText(FText::Format(
   625→					NSLOCTEXT("Cosmetic", "PurchaseCoinAmount", "{0} Coin 구매"),
   626→					FText::AsNumber(ItemDef->CoinPrice)));
   627→			}
   628→			else if (bGemAffordable)
   629→			{
   630→				ActionButton->SetIsEnabled(true);
   631→				ResetButtonTextColor();
   632→				ActionButtonText->SetText(FText::Format(
   633→					NSLOCTEXT("Cosmetic", "PurchaseGemAmount", "{0} Gem 구매"),
   634→					FText::AsNumber(ItemDef->GemPrice)));
   635→			}
   636→			else if (bHasCoinPrice || bHasGemPrice)
   637→			{
   638→				// 재화 가격이 있지만 잔액 부족
   639→				ActionButton->SetIsEnabled(false);
   640→				ActionButtonText->SetColorAndOpacity(FSlateColor(FLinearColor::Red));
   641→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "InsufficientBalance", "잔액 부족"));
   642→			}
   643→			else
   644→			{
   645→				// 재화 가격 없음 → Steam 실결제
   646→				ActionButton->SetIsEnabled(true);
   647→				ResetButtonTextColor();
   648→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Purchase", "구매"));
   649→			}
   650→		}
   651→	}
   652→	else
   653→	{
   654→		// 인벤토리 모드
   655→		ActionButton->SetIsEnabled(true);
   656→		ResetButtonTextColor();
   657→
   658→		if (bIsEquipped)
   659→		{
   660→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   661→		}
   662→		else
   663→		{
   664→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   665→		}
   666→	}
   667→}
