   742→void UCosmeticMainWindow::PopulateShopItems()
   743→{
   744→	UGameInstance* GI = GetGameInstance();
   745→	if (!GI)
   746→	{
   747→		return;
   748→	}
   749→
   750→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   751→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   752→	{
   753→		return;
   754→	}
   755→
   756→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   757→	TArray<const FCosmeticItemDefinition*> Items = Catalog->GetItemsBySlot(CurrentSlot);
   758→
   759→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   760→
   761→	int32 Index = 0;
   762→	for (const FCosmeticItemDefinition* ItemDef : Items)
   763→	{
   764→		if (!ItemDef || !ItemDef->IsValid())
   765→		{
   766→			continue;
   767→		}
   768→
   769→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   770→		if (!EntryWidget)
   771→		{
   772→			continue;
   773→		}
   774→
   775→		// 보유/장착 상태 설정
   776→		bool bOwned = CosmeticSub->HasItem(ItemDef->ItemId);
   777→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   778→
   779→		EntryWidget->SetOwned(bOwned);
   780→		EntryWidget->SetEquipped(bEquipped);
   781→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   782→
   783→		// 그리드에 추가
   784→		if (ItemGridPanel)
   785→		{
   786→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   787→		}
   788→
   789→		ItemEntryWidgets.Add(EntryWidget);
   790→		Index++;
   791→	}
   792→
   793→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d shop items"), Index);
   794→}
   795→
   796→void UCosmeticMainWindow::PopulateInventoryItems()
   797→{
   798→	UGameInstance* GI = GetGameInstance();
   799→	if (!GI)
   800→	{
   801→		return;
   802→	}
   803→
   804→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   805→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   806→	{
   807→		return;
   808→	}
   809→
   810→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   811→	const TArray<FCosmeticItemInstance>& Inventory = CosmeticSub->GetInventory();
   812→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   813→
   814→	int32 Index = 0;
   815→	for (const FCosmeticItemInstance& ItemInstance : Inventory)
   816→	{
   817→		const FCosmeticItemDefinition* ItemDef = Catalog->FindByItemId(ItemInstance.ItemId);
   818→		if (!ItemDef || !ItemDef->IsValid())
   819→		{
   820→			continue;
   821→		}
   822→
   823→		// 현재 슬롯에 해당하는 아이템만 표시
   824→		if (ItemDef->Slot != CurrentSlot)
   825→		{
   826→			continue;
   827→		}
   828→
   829→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   830→		if (!EntryWidget)
   831→		{
   832→			continue;
   833→		}
   834→
   835→		// 인벤토리 모드에서는 항상 보유 중
   836→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   837→
   838→		EntryWidget->SetOwned(true);
   839→		EntryWidget->SetEquipped(bEquipped);
   840→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   841→
   842→		// 그리드에 추가
   843→		if (ItemGridPanel)
   844→		{
   845→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   846→		}
   847→
   848→		ItemEntryWidgets.Add(EntryWidget);
   849→		Index++;
   850→	}
   851→
   852→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d inventory items"), Index);
   853→}
   854→
   855→UCosmeticItemEntryWidget* UCosmeticMainWindow::CreateItemEntry(const FCosmeticItemDefinition& Def)
   856→{
   857→	if (!ItemEntryWidgetClass)
   858→	{
   859→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CosmeticMainWindow: ItemEntryWidgetClass is not set"));
   860→		return nullptr;
   861→	}
   862→
   863→	UCosmeticItemEntryWidget* EntryWidget = CreateWidget<UCosmeticItemEntryWidget>(GetOwningPlayer(), ItemEntryWidgetClass);
   864→	if (!EntryWidget)
   865→	{
   866→		return nullptr;
   867→	}
   868→
   869→	EntryWidget->SetItemDefinition(Def);
   870→	EntryWidget->OnItemClicked.AddDynamic(this, &UCosmeticMainWindow::OnItemClicked);
   871→
   872→	return EntryWidget;
   873→}
   874→
   875→void UCosmeticMainWindow::ClearItemGrid()
   876→{
   877→	// 델리게이트 바인딩 해제 및 위젯 제거
   878→	for (UCosmeticItemEntryWidget* Entry : ItemEntryWidgets)
   879→	{
   880→		if (Entry)
   881→		{
   882→			Entry->OnItemClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnItemClicked);
   883→			Entry->RemoveFromParent();
   884→		}
   885→	}
   886→	ItemEntryWidgets.Empty();
   887→
   888→	// 그리드 클리어
   889→	if (ItemGridPanel)
   890→	{
   891→		ItemGridPanel->ClearChildren();
   892→	}
   893→}
