   895→void UCosmeticMainWindow::ShowNotification(const FText& Message, bool bSuccess)
   896→{
   897→	if (!NotificationText)
   898→	{
   899→		return;
   900→	}
   901→
   902→	NotificationText->SetText(Message);
   903→	NotificationText->SetColorAndOpacity(bSuccess
   904→		? FSlateColor(FLinearColor::Green)
   905→		: FSlateColor(FLinearColor::Red));
   906→	NotificationText->SetVisibility(ESlateVisibility::Visible);
   907→
   908→	// 기존 타이머 갱신
   909→	if (UWorld* World = GetWorld())
   910→	{
   911→		World->GetTimerManager().ClearTimer(NotificationTimerHandle);
   912→		World->GetTimerManager().SetTimer(
   913→			NotificationTimerHandle,
   914→			this,
   915→			&UCosmeticMainWindow::HideNotification,
   916→			NotificationDisplayDuration,
   917→			false
   918→		);
   919→	}
   920→}
   921→
   922→void UCosmeticMainWindow::HideNotification()
   923→{
   924→	if (NotificationText)
   925→	{
   926→		NotificationText->SetVisibility(ESlateVisibility::Hidden);
   927→	}
   928→}
