   218→void UWjWorldCosmeticSubsystem::StartInventoryPolling()
   219→{
   220→	UWorld* World = GetWorld();
   221→	if (!World)
   222→	{
   223→		return;
   224→	}
   225→
   226→	// 100ms 간격으로 결과 폴링
   227→	World->GetTimerManager().SetTimer(
   228→		InventoryPollTimerHandle,
   229→		this,
   230→		&UWjWorldCosmeticSubsystem::PollSteamInventoryResult,
   231→		0.1f,
   232→		true
   233→	);
   234→
