   238→void UWjWorldCosmeticSubsystem::StopInventoryPolling()
   239→{
   240→	UWorld* World = GetWorld();
   241→	if (World)
   242→	{
   243→		World->GetTimerManager().ClearTimer(InventoryPollTimerHandle);
   244→	}
