   250→void UWjWorldCosmeticSubsystem::PollSteamInventoryResult()
   251→{
   252→#if WITH_STEAM
   253→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   254→	{
   255→		StopInventoryPolling();
   256→		return;
   257→	}
   258→
   259→	ISteamInventory* SteamInv = SteamInventory();
   260→	if (!SteamInv)
   261→	{
   262→		StopInventoryPolling();
   263→		return;
   264→	}
   265→
   266→	EResult Status = SteamInv->GetResultStatus(PendingResultHandle);
   267→
   268→	if (Status == k_EResultPending)
   269→	{
   270→		// 아직 대기 중 - 계속 폴링
   271→		return;
   272→	}
   273→
   274→	// 결과 처리
   275→	if (Status == k_EResultOK)
   276→	{
   277→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 결과 수신 성공"));
   278→		ParseInventoryResult();
   279→	}
   280→	else
   281→	{
   282→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 결과 실패 (Status: %d)"), static_cast<int32>(Status));
   283→	}
   284→
   285→	// 정리
   286→	SteamInv->DestroyResult(PendingResultHandle);
   287→	PendingResultHandle = k_SteamInventoryResultInvalid;
   288→	StopInventoryPolling();
   289→
   290→	// 델리게이트 브로드캐스트
   291→	OnInventoryUpdated.Broadcast();
   292→#else
   293→	StopInventoryPolling();
   294→#endif
   295→}
   296→
   297→void UWjWorldCosmeticSubsystem::ParseInventoryResult()
   298→{
   299→#if WITH_STEAM
   300→	ISteamInventory* SteamInv = SteamInventory();
   301→	if (!SteamInv || !Catalog)
   302→	{
   303→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("ParseInventoryResult: SteamInventory 또는 Catalog 없음"));
   304→		return;
   305→	}
   306→
   307→	if (PendingResultHandle == k_SteamInventoryResultInvalid)
   308→	{
   309→		return;
   310→	}
   311→
   312→	// 아이템 개수 확인
   313→	uint32 ItemCount = 0;
   314→	if (!SteamInv->GetResultItems(PendingResultHandle, nullptr, &ItemCount) || ItemCount == 0)
   315→	{
   316→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리: 아이템 0개"));
   317→		CachedInventory.Empty();
   318→		return;
   319→	}
   320→
   321→	// 아이템 상세 정보 가져오기
   322→	TArray<SteamItemDetails_t> ItemDetails;
   323→	ItemDetails.SetNum(ItemCount);
   324→
   325→	if (!SteamInv->GetResultItems(PendingResultHandle, ItemDetails.GetData(), &ItemCount))
   326→	{
   327→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("Steam 인벤토리 아이템 상세 정보 가져오기 실패"));
   328→		return;
   329→	}
   330→
   331→	// 캐시된 인벤토리 갱신
   332→	CachedInventory.Empty(ItemCount);
   333→
   334→	for (uint32 i = 0; i < ItemCount; ++i)
   335→	{
   336→		const SteamItemDetails_t& Details = ItemDetails[i];
   337→
   338→		// SteamItemDefId → ItemId 변환
   339→		FName ItemId = Catalog->SteamItemDefIdToItemId(Details.m_iDefinition);
   340→		if (ItemId.IsNone())
   341→		{
   342→			UE_LOG(LogWjWorldCosmetic, Warning, TEXT("알 수 없는 SteamItemDefId: %d"), Details.m_iDefinition);
   343→			continue;
   344→		}
   345→
   346→		// 수량 체크 (0이면 소비됨/만료됨)
   347→		if (Details.m_unQuantity == 0)
   348→		{
   349→			continue;
   350→		}
   351→
   352→		// 기존 아이템 수량 증가 또는 새로 추가
   353→		FCosmeticItemInstance* Existing = CachedInventory.FindByPredicate([ItemId](const FCosmeticItemInstance& Inst)
   354→		{
   355→			return Inst.ItemId == ItemId;
   356→		});
   357→
   358→		if (Existing)
   359→		{
   360→			Existing->Quantity += Details.m_unQuantity;
   361→		}
   362→		else
   363→		{
   364→			FCosmeticItemInstance NewItem(ItemId);
   365→			NewItem.Quantity = Details.m_unQuantity;
   366→			CachedInventory.Add(NewItem);
   367→		}
   368→
   369→		UE_LOG(LogWjWorldCosmetic, Verbose, TEXT("인벤토리 아이템: %s (DefId: %d, Qty: %d)"),
   370→			*ItemId.ToString(), Details.m_iDefinition, Details.m_unQuantity);
   371→	}
   372→
   373→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("Steam 인벤토리 파싱 완료: %d개 아이템"), CachedInventory.Num());
   374→#endif
   375→}
