   443→bool UWjWorldCosmeticSubsystem::GenerateTestItem(FName ItemId)
   444→{
   445→#if WITH_STEAM && !UE_BUILD_SHIPPING
   446→	if (ItemId.IsNone())
   447→	{
   448→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: 유효하지 않은 ItemId"));
   449→		return false;
   450→	}
   451→
   452→	ISteamInventory* SteamInv = SteamInventory();
   453→	if (!SteamInv)
   454→	{
   455→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: Steam Inventory API 사용 불가"));
   456→		return false;
   457→	}
   458→
   459→	if (!Catalog)
   460→	{
   461→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: 카탈로그 없음"));
   462→		return false;
   463→	}
   464→
   465→	int32 SteamDefId = Catalog->ItemIdToSteamItemDefId(ItemId);
   466→	if (SteamDefId == 0)
   467→	{
