   469→		return false;
   470→	}
   471→
   472→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamDefId);
   473→	uint32 Quantity = 1;
   474→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
