   494→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("GenerateTestItem: 로컬 아이템 부여 (비Steam 환경) - %s"), *ItemId.ToString());
   495→	GrantItemLocally(ItemId, 1);
   496→	return true;
   497→#endif
   498→}
