   595→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   596→{
   597→	NewAmount = FMath::Max(0, NewAmount);
   598→
   599→	switch (Type)
   600→	{
   601→	case ECurrencyType::Coin:
   602→		if (CoinBalance != NewAmount)
   603→		{
   604→			CoinBalance = NewAmount;
   605→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   606→		}
   607→		break;
   608→	case ECurrencyType::Gem:
   609→		if (GemBalance != NewAmount)
   610→		{
   611→			GemBalance = NewAmount;
   612→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   613→		}
   614→		break;
   615→	}
   616→}
